#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;
int main() {
    int n;
    scanf("%d", &n);
    vector<vector<int>> a(n, vector<int>(n, 0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= i; j++) {
            scanf("%d", &a[i][j]);
            if (i > 0) {
                if (j == 0){
                    a[i][j] += a[i - 1][j];
                } else {
                    a[i][j] += max(a[i - 1][j], a[i - 1][j - 1]);
                }
            }
        }
    }
    int res = 0;
    for (int j = 0; j < n; j++) {
        res = max(res, a[n - 1][j]);
    }
    printf("%d", res);
    return 0;
}
